mapper.select:
SELECT r.*, u.nickname AS username, s.name AS spu_name
FROM stellar_review r
LEFT JOIN stellar_mall_user u ON u.id = r.user_id
LEFT JOIN stellar_spu s ON s.id = r.spu_id

    AND r.spu_id = #{spuId}
    AND r.status = #{status}
    AND s.name LIKE CONCAT('%', #{spuName}, '%')

ORDER BY r.create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM stellar_review r
LEFT JOIN stellar_spu s ON s.id = r.spu_id

    AND r.spu_id = #{spuId}
    AND r.status = #{status}
    AND s.name LIKE CONCAT('%', #{spuName}, '%')
